export default function SocialHomeClient({ userId, profile, initialPosts, authors, personalMedia, capabilities }: { userId: string; profile: Profile; initialPosts: Post[]; authors: Profile[]; personalMedia: PersonalMedia[]; capabilities: Capabilities }) {
  const supabase = useMemo(() => createClient(), []);
  const [posts, setPosts] = useState(initialPosts);
  const [body, setBody] = useState("");
  const [visibility, setVisibility] = useState("connections");
  const [selectedMediaIds, setSelectedMediaIds] = useState<string[]>([]);
  const [showMedia, setShowMedia] = useState(false);
  const [busy, setBusy] = useState(false);
  const [notice, setNotice] = useState("");
  const [realtimeState, setRealtimeState] = useState<"connecting" | "live" | "error">("connecting");
  const authorMap = useMemo(() => new Map(authors.map((author) => [author.id, author])), [authors]);
  const unavailable = capabilityLabels.filter(([key]) => !capabilities[key]);

